const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const leads=[{name:'Mariana Costa',company:'Nuvem Tech',city:'São Paulo',sector:'Tecnologia',role:'Diretora comercial',fit:94,color:'purple',initials:'MC'},{name:'Rafael Almeida',company:'Horizonte Soluções',city:'Curitiba',sector:'Serviços',role:'Sócio fundador',fit:91,color:'peach',initials:'RA'},{name:'Juliana Santos',company:'Atlas Industrial',city:'Belo Horizonte',sector:'Indústria',role:'Gerente comercial',fit:88,color:'blue',initials:'JS'}];
const avatar=l=>`<span class="avatar ${l.color}">${l.initials}</span>`;
const leadRows=()=>leads.map(l=>`<div class="lead-row">${avatar(l)}<div><strong>${l.name}</strong><small>${l.company} · ${l.city}</small></div><span class="fit">${l.fit}% fit</span></div>`).join('');
const visualRows=()=>leads.map(l=>`<div class="visual-row"><span class="check">✓</span>${avatar(l)}<div><strong>${l.company}</strong><small>${l.sector} · ${l.city}</small></div><span class="fit">${l.fit}% fit</span></div>`).join('');
function chart(){return `<svg class="line-chart" viewBox="0 0 460 170" role="img" aria-label="Gráfico ilustrativo de aberturas e respostas ao longo de sete dias"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#b80011" stop-opacity=".17"/><stop offset="1" stop-color="#b80011" stop-opacity="0"/></linearGradient></defs><path class="grid-line" d="M10 30H450M10 75H450M10 120H450M10 165H450"/><path fill="url(#area)" d="M10 144C50 144 50 110 82 114S132 149 157 103S213 109 230 78S281 107 307 66S358 74 380 39S425 55 450 12V170H10Z"/><path class="chart-line" d="M10 144C50 144 50 110 82 114S132 149 157 103S213 109 230 78S281 107 307 66S358 74 380 39S425 55 450 12"/><path class="chart-line secondary" d="M10 156C50 156 60 144 90 147S142 136 165 139S210 113 245 126S285 101 315 108S367 78 395 89S430 62 450 60"/></svg>`}
const miniChart=()=>`<div class="mini-chart">${[35,52,44,72,60,85,96].map((h,i)=>`<div style="--h:${h}%;--d:${i*.09}s"></div>`).join('')}</div><div class="mini-chart-label"><span>Seg</span><span>Ter</span><span>Qua</span><span>Qui</span><span>Sex</span><span>Sáb</span><span>Dom</span></div>`;
const copyMini=()=>`<div class="mini-panel"><div class="panel-heading">Sua próxima abordagem <span>✦ BAZHI IA</span></div><div class="mini-copy"><strong>Uma ideia para a próxima fase da Nuvem</strong><p>Olá, Mariana! Vi que a <mark>Nuvem Tech está expandindo sua operação</mark>. Que tal conectar seu time às empresas certas?</p></div><button class="mini-copy-action" data-demo>Revisar abordagem <span>↗</span></button></div>`;
const campaignVisual=()=>`<div class="flow-campaign"><div><i>✦</i><span>Copy personalizada<small>Revisada e pronta para a abordagem</small></span><b>✓ Pronto</b></div><div><i>➤</i><span>E-mail de apresentação<small>Primeiro contato com a empresa</small></span><b>Em fila</b></div><div><i>↗</i><span>Acompanhamento<small>Observe respostas e próximos passos</small></span><b>Insights</b></div></div>`;
function screen(i=0){const titles=['Seu próximo negócio começa aqui.','Encontre as empresas certas.','Cada abordagem, um contexto.','Da copy à próxima conversa.','Entenda o que move sua campanha.'];let content='';if(i===0)content=`<div class="mini-stats">${[['Empresas encontradas','128','↗ Perfil ideal'],['Abordagens criadas','86','✦ Com IA'],['E-mails enviados','64','↗ Campanha'],['Novas respostas','18','↗ Conversas']].map(x=>`<div class="mini-stat"><span>${x[0]}</span><div>${x[1]}<small>${x[2]}</small></div></div>`).join('')}</div><div class="app-panels"><div class="mini-panel"><div class="panel-heading">Empresas para sua próxima conversa <small>VER TODAS ↗</small></div>${leadRows()}</div>${copyMini()}</div>`;
if(i===1)content=`<div class="mini-panel"><div class="panel-heading">Empresas no Brasil <small>3 EXEMPLOS FICTÍCIOS</small></div>${visualRows()}<div class="visual-summary">Segmento, região e perfil <b>Filtros na demo ↗</b></div></div>`;
if(i===2)content=`<div style="max-width:500px">${copyMini()}<button class="text-link" data-demo>Personalizar uma abordagem ↗</button></div>`;
if(i===3)content=`<div class="mini-panel"><div class="panel-heading">Campanha de prospecção <small>SIMULAÇÃO</small></div>${campaignVisual()}</div>`;
if(i===4)content=`<div class="mini-panel"><div class="panel-heading">Desempenho da campanha <small>DADOS ILUSTRATIVOS</small></div>${miniChart()}</div>`;
$('#app-main').innerHTML=`<div class="app-greeting"><div><h3>${titles[i]}</h3><p>Sua operação de prospecção, em uma visão conectada.</p></div><span>Últimos 7 dias ⌄</span></div>${content}<div class="app-footer"><span>● Sua próxima oportunidade está em movimento</span><span>Dados demonstrativos</span></div>`;$$('[data-screen]').forEach(b=>{const active=+b.dataset.screen===i;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));b.setAttribute('aria-controls','app-main');});}
const steps=[{title:'Seu cliente ideal.<br>Uma busca de distância.',text:'Defina o perfil e encontre empresas no Brasil que fazem sentido para sua abordagem.',label:'ENCONTRE QUEM IMPORTA',visual:()=>`<div class="visual-toolbar"><span>▦ Empresas para prospectar</span><span>Perfil ideal ✓</span></div><div class="filter-tags"><span>Brasil ⌄</span><span>Segmento ⌄</span><span>Porte ⌄</span></div>${visualRows()}<div class="visual-summary">3 empresas no perfil <b>Próximo: personalizar →</b></div>`},{title:'Parece escrita por você.<br>Porque tem contexto.',text:'Use IA para transformar informações da empresa em uma copy personalizada. Revise antes de seguir.',label:'UMA ABORDAGEM PARA CADA EMPRESA',visual:()=>`<div class="visual-toolbar"><span>✦ Personalização com IA</span><span>Contexto → Copy</span></div><div class="full-copy"><strong>Para: Mariana · Nuvem Tech</strong><p>Olá, Mariana! Vi que a Nuvem Tech está em um momento de expansão.</p><p>Uma operação de prospecção mais conectada pode ajudar seu time a encontrar as empresas certas para essa próxima fase.</p><p>Faz sentido conversarmos sobre isso?</p><span class="cursor"></span></div><div class="visual-summary">Contexto de empresa aplicado <b>✓ Pronta para revisar</b></div>`},{title:'Revisou?<br>Hora de abrir a conversa.',text:'Organize a abordagem, revise os destinatários e acompanhe o caminho de cada envio.',label:'DA MENSAGEM À AÇÃO',visual:()=>`<div class="visual-toolbar"><span>➤ Sua campanha</span><span>Do início ao envio</span></div>${campaignVisual()}`},{title:'Cada interação.<br>Um insight para melhorar.',text:'Veja os resultados da campanha e use os sinais de interesse para ajustar a próxima abordagem.',label:'APRENDA COM CADA RESPOSTA',visual:()=>`<div class="visual-toolbar"><span>▥ Insights da campanha</span><span>Últimos 7 dias · Exemplo</span></div>${miniChart()}<div class="visual-summary">Aprenda com o desempenho <b>↗ Próxima melhor ação</b></div>`}];
function setStep(i){
 const s=steps[i],panel=$('#process-panel');
 const arrowFocus=document.activeElement?.getAttribute('data-step-move');
 const old=Number(panel.dataset.current||0);
 panel.dataset.direction=i>=old?'next':'previous';panel.dataset.current=String(i);
 const titles=['Encontre empresas.<br>Escolha com contexto.','Personalize a abordagem.<br>Com IA e sua voz.','Revise. Envie.<br>Abra a conversa.','Transforme respostas<br>em próximos passos.'];
 const points=[['Segmento','Região','Perfil ideal'],['Contexto da empresa','Tom da mensagem','Sua revisão'],['Destinatários','Mensagem revisada','Acompanhamento'],['Interações','Respostas','Próximas ações']];
 $$('[data-step]').forEach(b=>{const active=+b.dataset.step===i;b.setAttribute('aria-selected',active);b.setAttribute('tabindex',active?'0':'-1');b.setAttribute('aria-controls','process-panel');});
 panel.setAttribute('aria-labelledby','process-tab-'+i);
 panel.innerHTML=`<div class="process-copy"><span class="step-overline"><b>0${i+1}</b> ${s.label}</span><h3>${titles[i]}</h3><p>${s.text}</p><div class="step-keywords">${points[i].map(x=>`<span>${x}</span>`).join('')}</div><button class="step-demo" data-demo>Experimente essa etapa <span>↗</span></button></div><div class="process-visual">${s.visual()}${i===1?'<div class="live-copy-tools"><span>Teste uma variação de abordagem</span><button type="button" data-step-copy>✦ Gerar outra versão</button></div>':''}</div><div class="process-navigation"><span class="step-counter"><b>0${i+1}</b> / 04 <i></i> ${['Encontre empresas','Copy com IA','Envie abordagens','Acompanhe insights'][i]}</span><div><button type="button" data-step-move="-1" aria-label="Etapa anterior" ${i===0?'disabled':''}>←</button><button type="button" data-step-move="1" aria-label="Próxima etapa" ${i===3?'disabled':''}>→</button></div></div>`;
 const status=$('#process-status');if(status)status.textContent=`Etapa ${i+1} de 4: ${['Encontre empresas','Copy com IA','Envie abordagens','Acompanhe insights'][i]}.`;
 if(arrowFocus!=null){const control=panel.querySelector(`[data-step-move="${arrowFocus}"]:not(:disabled)`)||panel.querySelector('[data-step-move]:not(:disabled)');control?.focus({preventScroll:true});}
}
function bigCopy(){return `<div class="copy-visual"><div class="company-context"><i>N</i><div><strong>Nuvem Tech</strong><small>Software · São Paulo</small></div><span>Contexto analisado ✓</span></div><div class="copy-divider"><span>✦</span><i></i> BAZHI IA <i></i></div><div class="email-preview"><div class="email-meta"><span>Para: Mariana · Nuvem Tech</span><span>✦ Personalizado</span></div><strong id="bento-subject">Uma ideia para a próxima fase da Nuvem</strong><div id="bento-email"><p>Olá, Mariana! Vi que a <mark>Nuvem Tech está expandindo sua operação</mark>. Quando o time cresce, encontrar as empresas certas faz toda a diferença.</p><p>Que tal conversar sobre uma prospecção mais conectada ao seu momento?</p></div><span class="cursor"></span></div><div class="ai-edit"><button data-tone="direto">↗ Mais direto</button><button data-tone="consultivo">✦ Mais consultivo</button><button data-demo>Editar na demo →</button></div></div>`}
function bigInsight(){return `<div class="insight-visual"><div class="insight-top"><span>Desempenho da campanha<small>Dados de exemplo · Últimos 7 dias</small></span><b>↗ +24%</b></div><div class="chart-legend"><span>Aberturas</span><span>Respostas</span></div>${chart()}<div class="chart-days">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(x=>`<span>${x}</span>`).join('')}</div><div class="insight-metrics"><div><span>Aberturas</span><b>68%</b></div><div><span>Respostas</span><b>24%</b></div><div><span>Conversas</span><b>18</b></div></div><div class="ai-insight"><span>✦</span><div><strong>O que está funcionando?</strong><small>Compare abordagens e encontre o próximo ajuste.</small></div></div></div>`}
const sectors=[['Tecnologia','SaaS, software e TI','⌘','✦'],['Serviços','Consultorias e negócios B2B','◈','↔'],['Indústria','Operações e cadeia produtiva','▥','↗'],['Agências','Marketing e comunicação','✳','◎']];
const faqs=[["O que a Bazhi faz pelo meu comercial?", "A Bazhi conecta o caminho entre encontrar uma empresa e iniciar uma conversa. Com uma base interna de mais de 20 milhões de empresas brasileiras, você define o perfil de cliente que quer alcançar, prospecta empresas, cria um modelo de copy e usa IA para adaptar a abordagem ao contexto de cada negócio. Depois, organiza os envios em cadências e acompanha os insights para ajustar os próximos passos."], ["Como funciona o teste grátis?", "Você pode prospectar e abordar 30 empresas gratuitamente. É a oportunidade de conhecer o fluxo completo: encontrar negócios com o perfil desejado, preparar sua mensagem, personalizar com IA e acompanhar os primeiros retornos. Comece com uma lista enxuta e veja como a Bazhi se encaixa na sua operação."], ["Posso ser bloqueado por spam?", "Personalização e cadência ajudam a reduzir os riscos, mas não eliminam a possibilidade de bloqueio. A proposta da Bazhi é criar abordagens individuais e distribuir os envios respeitando os limites configurados para a conexão SMTP. A entrega também depende da reputação do domínio, da autenticação do e-mail, da qualidade dos contatos e das regras do provedor. Uma mensagem personalizada, sozinha, não garante que o e-mail chegue à caixa de entrada."], ["A IA cria uma abordagem para cada empresa?", "Sim. Você define a oferta, o tom e a direção da conversa no modelo de copy. A IA combina essa base com as informações disponíveis sobre a empresa destinatária para adaptar a mensagem ao negócio que vai recebê-la. A ideia é ir além de trocar um nome: usar o contexto disponível para dar à abordagem um motivo para existir, sem inventar informações."], ["O que posso revisar antes dos envios?", "Você pode revisar e ajustar o modelo de copy: a proposta, o tom e a estrutura da mensagem. A partir dessa base, a IA acrescenta o contexto e as variáveis de cada empresa. O fluxo não oferece revisão individual de cada disparo; por isso, a revisão do modelo define a direção das versões personalizadas. Você controla a mensagem-base, e a IA adapta o contexto de cada negócio."]];
faqs.push(['Como a Bazhi verifica os e-mails?','A Bazhi utiliza camadas de verificação antes da tentativa de envio e mantém testes contínuos para aprimorar a validação. Esse cuidado ajuda a avaliar os contatos, mas não representa uma promessa de entrega na caixa de entrada.'],['Perco crédito se o envio não for realizado?','Não. Você é cobrado pelos e-mails efetivamente enviados. Se a tentativa não resultar em envio, o crédito utilizado volta ao seu saldo e pode ser usado em outra oportunidade.']);
function faq(q=''){const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();$('#faq-list').innerHTML=faqs.map((f,i)=>({f,i})).filter(({f})=>normalize(f.join(' ')).includes(normalize(q))).map(({f,i})=>`<details ${i===0?'open':''}><summary><span class="faq-question">${f[0]}</span><span class="faq-plus" aria-hidden="true">+</span></summary><div class="faq-answer"><p>${f[1]}</p></div></details>`).join('')||'<p>Nenhuma dúvida encontrada. Tente “IA”, “teste” ou “envio”.</p>';}
let state={step:0,sector:'Tecnologia',region:'Todo o Brasil',selected:[0,1,2],subject:'',copy:'',tone:'Consultivo'},demoSession=0;
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function demoLeads(){const companyNames={'Tecnologia':['Nuvem Tech','Órbita Software','Ponto Digital'],'Serviços':['Horizonte Soluções','Prisma Consultoria','Norte Serviços'],'Indústria':['Atlas Industrial','Vértice Indústria','Aurora Máquinas'],'Agências':['Estúdio Conecta','Agência Horizonte','Ponto Criativo']};return leads.map((l,i)=>({...l,company:companyNames[state.sector][i],city:state.region==='Todo o Brasil'?l.city:state.region,sector:state.sector}));}
function copyFor(){const l=demoLeads()[state.selected[0]]||demoLeads()[0];return state.tone==='Direto'?`Olá, ${l.name.split(' ')[0]}!\n\nTenho uma ideia para a prospecção da ${l.company}: encontrar empresas com o perfil certo e iniciar conversas com abordagens personalizadas.\n\nVocê teria 15 minutos para explorarmos como isso se encaixa no seu time?`:`Olá, ${l.name.split(' ')[0]}!\n\nAo conhecer a ${l.company} e sua atuação em ${l.sector.toLowerCase()}, pensei em como uma prospecção mais conectada ao contexto de cada empresa pode apoiar seu time comercial.\n\nQue tal conversarmos sobre formas de encontrar novas oportunidades com abordagens mais relevantes?\n\nFaz sentido para o momento de vocês?`;}
function saveCopy(){if($('#copy-subject')){state.subject=$('#copy-subject').value;state.copy=$('#copy-message').value;}}
function demoStep(step){state.step=step;$$('.demo-steps span').forEach((s,i)=>s.classList.toggle('active',i===(step===0||step===1?0:step-1)));const target=$('#demo-content');let html='';
if(step===0)html=`<h2 id="demo-title">Quem você quer abordar?</h2><p>Defina um perfil para explorar o fluxo de prospecção.</p><form class="demo-form" id="demo-search"><label>Segmento<select name="sector">${sectors.map(x=>`<option ${state.sector===x[0]?'selected':''}>${x[0]}</option>`).join('')}</select></label><label>Região<select name="region">${['Todo o Brasil','São Paulo','Curitiba','Belo Horizonte'].map(x=>`<option ${state.region===x?'selected':''}>${x}</option>`).join('')}</select></label><button class="button" type="submit">Encontrar empresas <span>↗</span></button></form>`;
if(step===1)html=`<h2 id="demo-title">Sua próxima lista de empresas.</h2><p>${state.sector} · ${state.region} · Selecione quem entra na abordagem.</p><div class="demo-list">${demoLeads().map((l,i)=>`<label class="demo-company"><input type="checkbox" name="lead" value="${i}" ${state.selected.includes(i)?'checked':''}>${avatar(l)}<div><strong>${l.company}</strong><small>${l.name} · ${l.city}</small></div><span class="fit">${l.fit}% fit</span></label>`).join('')}</div><div class="demo-actions"><button class="back-button" data-back="0">← Alterar filtros</button><button class="button" id="create-copy">Criar copy com IA <span>✦</span></button></div>`;
if(step===2){if(!state.copy){state.copy=copyFor();state.subject=`Uma ideia para a ${demoLeads()[state.selected[0]].company}`;}html=`<h2 id="demo-title">Contexto que vira conversa.</h2><p>Exemplo personalizado para ${escapeHTML(demoLeads()[state.selected[0]].company)}. Edite antes de continuar.</p><div class="demo-copy-box"><label>Assunto<input id="copy-subject" value="${escapeHTML(state.subject)}" maxlength="160"></label><label>Mensagem<textarea id="copy-message">${escapeHTML(state.copy)}</textarea></label><div class="demo-copy-tools"><select aria-label="Tom da mensagem" id="copy-tone"><option ${state.tone==='Consultivo'?'selected':''}>Consultivo</option><option ${state.tone==='Direto'?'selected':''}>Direto</option></select><button id="regenerate">✦ Gerar outra versão</button></div></div><div class="demo-actions"><button class="back-button" data-back="1">← Ver empresas</button><button class="button" id="review-campaign">Revisar campanha <span>→</span></button></div>`;}
if(step===3)html=`<h2 id="demo-title">Tudo pronto para abrir a conversa.</h2><p>Revise a campanha antes de simular o envio.</p><div class="demo-campaign"><div><span>Segmento</span><strong>${state.sector}</strong></div><div><span>Região</span><strong>${state.region}</strong></div><div><span>Destinatários</span><strong>${state.selected.length} contatos fictícios</strong></div><div><span>Assunto</span><strong>${escapeHTML(state.subject)}</strong></div><div><span>Canal demonstrado</span><strong>E-mail</strong></div></div><div class="demo-actions"><button class="back-button" data-back="2">← Editar mensagem</button><button class="button" id="simulate-send">Simular envio <span>➤</span></button></div>`;
if(step===4){const n=state.selected.length;html=`<h2 id="demo-title">Agora, transforme sinais em insights.</h2><p>Veja como seria acompanhar uma campanha. Estes resultados são ilustrativos.</p><div class="demo-metrics"><div><span>Envios simulados</span><b>${n}</b></div><div><span>Aberturas de exemplo</span><b>${n}</b></div><div><span>Respostas de exemplo</span><b>1</b></div></div><div class="mini-panel"><div class="panel-heading">Evolução ilustrativa da campanha <small>EXEMPLO</small></div>${miniChart()}</div><div class="demo-insight">✦ Próxima ação sugerida: revisar a resposta e continuar a conversa com o contexto da empresa.</div><div class="demo-actions"><button class="back-button" id="restart-demo">← Explorar outro perfil</button><button class="button" data-close>Concluir demonstração ✓</button></div>`;}
target.innerHTML=`<div class="demo-body">${html}</div>`;const heading=$('#demo-title');heading.setAttribute('tabindex','-1');if($('#demo-dialog').open)heading.focus({preventScroll:true});$('#demo-dialog').scrollTop=0;}
function openDemo(sector){demoSession++;state={step:0,sector:sector||'Tecnologia',region:'Todo o Brasil',selected:[0,1,2],subject:'',copy:'',tone:'Consultivo'};demoStep(0);$('#demo-dialog').showModal();$('#demo-title').focus({preventScroll:true});}
let toastTimer;function toast(s){$('.toast').textContent=s;$('.toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('.toast').classList.remove('show'),2500);}
document.addEventListener('click',e=>{const demo=e.target.closest('[data-demo]');if(demo)openDemo();const sector=e.target.closest('[data-sector]');if(sector)openDemo(sector.dataset.sector);const s=e.target.closest('[data-screen]');if(s)screen(+s.dataset.screen);const step=e.target.closest('[data-step]');if(step)setStep(+step.dataset.step);const back=e.target.closest('[data-back]');if(back){saveCopy();demoStep(+back.dataset.back);}if(e.target.closest('.close')||e.target.closest('[data-close]')){(e.target.closest('dialog')||$('#demo-dialog')).close();demoSession++;}if(e.target.closest('#create-copy')){state.selected=$$('input[name=lead]:checked').map(x=>+x.value);if(!state.selected.length)return toast('Selecione ao menos uma empresa.');state.copy='';demoStep(2);}if(e.target.closest('#review-campaign')){saveCopy();if(!state.copy.trim()||!state.subject.trim())return toast('Preencha o assunto e a mensagem.');demoStep(3);}if(e.target.closest('#regenerate')){state.tone=$('#copy-tone').value;state.copy=copyFor();demoStep(2);toast('Nova versão demonstrativa criada.');}if(e.target.closest('#simulate-send')){const session=demoSession;$('#demo-content').innerHTML='<div class="send-animation"><span>➤</span><div><strong>Simulando sua campanha…</strong><small>Nenhuma mensagem real está sendo enviada.</small></div></div>';setTimeout(()=>{if(session===demoSession&&$('#demo-dialog').open)demoStep(4);},1300);}if(e.target.closest('#restart-demo'))demoStep(0);const tone=e.target.closest('[data-tone]');if(tone){$('#bento-subject').textContent=tone.dataset.tone==='direto'?'Vamos conversar sobre a Nuvem?':'Uma ideia para a próxima fase da Nuvem';$('#bento-email').innerHTML=tone.dataset.tone==='direto'?'<p>Olá, Mariana! Tenho uma ideia para a <mark>prospecção da Nuvem Tech</mark>: encontrar o perfil certo e iniciar conversas relevantes.</p><p>Você tem 15 minutos para conversar nesta semana?</p>':'<p>Olá, Mariana! Vi que a <mark>Nuvem Tech está expandindo sua operação</mark>. Quando o time cresce, encontrar as empresas certas faz toda a diferença.</p><p>Que tal conversar sobre uma prospecção mais conectada ao seu momento?</p>';toast('Tom da mensagem atualizado.');}});
document.addEventListener('submit',e=>{if(e.target.id==='demo-search'){e.preventDefault();const f=new FormData(e.target);state.sector=f.get('sector');state.region=f.get('region');state.selected=[0,1,2];state.copy='';demoStep(1);}});
$$('[role=tablist]').forEach(list=>list.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const tabs=[...list.querySelectorAll('[role=tab]')],i=tabs.indexOf(document.activeElement);if(i<0)return;e.preventDefault();const j=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[j].focus();tabs[j].click();}));
$('.faq-search input')?.addEventListener('input',e=>faq(e.target.value));$('#privacy').addEventListener('click',()=>$('#privacy-dialog').showModal());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('#copy-visual').innerHTML=bigCopy();$('#insight-visual').innerHTML=bigInsight();$('#year').textContent=new Date().getFullYear();screen();setStep(0);faq();
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;$$('.reveal').forEach(x=>x.classList.add('visible'));

$$('.sector-art').forEach((el,i)=>{el.classList.add('ai-image');el.style.backgroundPosition=(i*100/3)+'% center';});
const connectionSteps=[
 ['01 / DESCOBERTA','▦','Comece pela empresa certa.','O perfil da empresa dá direção à abordagem. Segmento e região entram na conversa antes da primeira mensagem.'],
 ['02 / PERSONALIZAÇÃO','✦','Contexto que vira uma boa abertura.','Use a IA para transformar informações da empresa em uma mensagem relevante. Ajuste o tom e revise antes de avançar.'],
 ['03 / CONTEXTO','◎','O detalhe muda a conversa.','Conecte o perfil da empresa ao motivo do contato. Uma abordagem começa melhor quando existe uma razão clara para conversar.'],
 ['04 / ABORDAGEM','↗','Da revisão ao próximo contato.','Organize a mensagem e os destinatários antes de enviar. Na demonstração, você percorre esse caminho sem realizar envios reais.'],
 ['05 / RELACIONAMENTO','↔','Respostas abrem novos caminhos.','O trabalho não termina no envio. Use o contexto da empresa para conduzir a conversa e definir o próximo passo com seu time.'],
 ['06 / APRENDIZADO','▥','Aprenda com cada interação.','Acompanhe os sinais da campanha para entender o que merece atenção e refinar a próxima abordagem.']
];
document.querySelectorAll('[data-connection]').forEach(button=>button.addEventListener('click',()=>{
 const entry=connectionSteps[Number(button.dataset.connection)];
 document.querySelectorAll('[data-connection]').forEach(node=>{const active=node===button;node.classList.toggle('is-active',active);node.setAttribute('aria-pressed',String(active));});
 ['connection-index','connection-icon','connection-name','connection-text'].forEach((id,index)=>document.getElementById(id).textContent=entry[index]);
 const detail=document.querySelector('.connection-detail');detail.classList.remove('is-switching');requestAnimationFrame(()=>detail.classList.add('is-switching'));
}));
